export function weightedConfidenceTree(agents, ideas) {
  const weightedVotes = ideas.map(idea => {
    const votes = agents.map(agent => agent.voteOnIdea(idea));
    const weightedScore = votes.reduce((acc, vote) => acc + vote.confidence * vote.weight, 0);
    return { idea, weightedScore };
  });
  return weightedVotes.sort((a, b) => b.weightedScore - a.weightedScore);
}

